{
  "title": "Conversation Overview",
  "body": "<div class="panel">
  <header class="header">
    <div class="title-bar">
      <h2>Conversation Stats</h2>
      <span class="badge-live">Live</span>
    </div>
    <p class="subtitle">Real-time message and tool telemetry</p>
  </header>

  <section class="section">
    <h3 class="section-title">Messages by Role</h3>
    <div class="roles-grid" id="roles-container"></div>
  </section>

  <section class="section">
    <h3 class="section-title">Longest Message</h3>
    <div class="metric-card">
      <div class="metric-value" id="longest-val">0</div>
      <div class="metric-details">
        <span class="metric-unit">characters</span>
        <span class="metric-sub" id="longest-meta">None</span>
      </div>
    </div>
  </section>

  <section class="section">
    <h3 class="section-title">Recent Tool Calls</h3>
    <div class="tools-card" id="tools-container"></div>
  </section>
</div>",
  "css": "* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
  padding: 16px;
  line-height: 1.4;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 480px;
  margin: 0 auto;
}

.header {
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 12px;
}

.title-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

h2 {
  font-size: 1.15rem;
  font-weight: 700;
  color: #0f172a;
}

.subtitle {
  font-size: 0.8rem;
  color: #64748b;
  margin-top: 2px;
}

.badge-live {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background-color: #dcfce7;
  color: #15803d;
  padding: 2px 8px;
  border-radius: 9999px;
  border: 1px solid #bbf7d0;
}

.section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #64748b;
}

.roles-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.role-badge {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 8px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.role-label {
  font-size: 0.82rem;
  font-weight: 500;
  text-transform: capitalize;
  color: #475569;
}

.role-num {
  font-size: 1.05rem;
  font-weight: 700;
  color: #0f172a;
}

.role-user .role-label { color: #2563eb; }
.role-assistant .role-label { color: #059669; }
.role-system .role-label { color: #7c3aed; }
.role-tool .role-label { color: #d97706; }

.metric-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 12px 14px;
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.metric-value {
  font-size: 1.8rem;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.02em;
}

.metric-details {
  display: flex;
  flex-direction: column;
}

.metric-unit {
  font-size: 0.8rem;
  font-weight: 600;
  color: #475569;
}

.metric-sub {
  font-size: 0.75rem;
  color: #94a3b8;
  text-transform: capitalize;
}

.tools-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tool-entry {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-bottom: 1px solid #f1f5f9;
}

.tool-entry:last-child {
  border-bottom: none;
}

.tool-rank {
  font-size: 0.7rem;
  font-weight: 700;
  color: #94a3b8;
  width: 20px;
}

.tool-name {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.8rem;
  color: #0f172a;
  background: #f1f5f9;
  padding: 2px 6px;
  border-radius: 4px;
  word-break: break-all;
}

.empty-tools {
  padding: 16px 12px;
  text-align: center;
  font-size: 0.8rem;
  color: #94a3b8;
  font-style: italic;
}",
  "scripts": [
    "const messages = ml.current?.messages ?? [];

const roleCounts = {
  system: 0,
  user: 0,
  assistant: 0,
  tool: 0
};

let maxLen = 0;
let maxLenRole = "none";
const allToolCalls = [];

for (const m of messages) {
  const r = m.role ?? "unknown";
  if (roleCounts[r] === undefined) {
    roleCounts[r] = 0;
  }
  roleCounts[r] = roleCounts[r] + 1;

  const content = m.content ?? "";
  const len = content.length;
  if (len > maxLen) {
    maxLen = len;
    maxLenRole = r;
  }

  const calls = m.tool_calls;
  if (Array.isArray(calls)) {
    for (const tc of calls) {
      const name = tc?.function?.name ?? "anonymous_tool";
      allToolCalls.push(name);
    }
  }
}

const formatNum = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");

const rolesNode = root.byId["roles-container"];
if (rolesNode) {
  rolesNode.children = Object.keys(roleCounts).map((role) => ({
    tag: "div",
    attrs: { class: "role-badge role-" + role },
    children: [
      { tag: "span", attrs: { class: "role-label" }, text: role },
      { tag: "span", attrs: { class: "role-num" }, text: formatNum(roleCounts[role]) }
    ]
  }));
}

const longestValNode = root.byId["longest-val"];
if (longestValNode) {
  longestValNode.text = formatNum(maxLen);
}

const longestMetaNode = root.byId["longest-meta"];
if (longestMetaNode) {
  longestMetaNode.text = maxLen > 0 ? "from " + maxLenRole : "none";
}

const toolsNode = root.byId["tools-container"];
if (toolsNode) {
  const recent = allToolCalls.slice(-5).reverse();
  if (recent.length === 0) {
    toolsNode.children = [
      {
        tag: "div",
        attrs: { class: "empty-tools" },
        text: "No tool calls recorded yet"
      }
    ];
  } else {
    toolsNode.children = recent.map((name, idx) => ({
      tag: "div",
      attrs: { class: "tool-entry" },
      children: [
        { tag: "span", attrs: { class: "tool-rank" }, text: "#" + String(idx + 1) },
        { tag: "code", attrs: { class: "tool-name" }, text: name }
      ]
    }));
  }
}"
  ]
}
